const ARCHIVE_DATE = '2026-07-24';

const slugify = (value = '') => String(value)
  .normalize('NFKD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase()
  .replace(/&/g, ' and ')
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '');

const unique = (values) => [...new Set(values.filter(Boolean))];
const chapterSourceId = (number) => `source:chapter-${number}`;
const characterId = (name) => `character:${slugify(name)}`;
const organizationId = (slug) => `organization:${slug}`;
const guardianBeastId = (host) => `guardian-beast:${slugify(host)}`;

const base = ({ id, entityType, slug, name, summary, sourceIds, canonLevel = 'canon', aliases = [] }) => Object.freeze({
  id,
  entityType,
  slug,
  name,
  aliases: Object.freeze(aliases),
  summary,
  sourceIds: Object.freeze(unique(sourceIds)),
  publicationStatus: 'published',
  canonLevel,
  createdAt: ARCHIVE_DATE,
  updatedAt: ARCHIVE_DATE,
});

const ability = ({ slug, name, summary, ownerIds = [], nenTypes = ['unknown'], certainty = 'confirmed', category, activation, conditions = [], limitations = [], costs = [], knownUses = [], sources, canonLevel = 'canon', aliases = [] }) => Object.freeze({
  ...base({ id: `ability:${slug}`, entityType: 'ability', slug, name, summary, sourceIds: sources.map(chapterSourceId), canonLevel, aliases }),
  ownerIds: Object.freeze(ownerIds),
  classification: Object.freeze({ nenTypes: Object.freeze(nenTypes), certainty }),
  category,
  activation,
  conditions: Object.freeze(conditions),
  limitations: Object.freeze(limitations),
  costs: Object.freeze(costs),
  knownUses: Object.freeze(knownUses),
});

