const event = ({ slug, name, summary, category, importance = 'major', start, end = start, participants = [], organizations = [], locations = [], abilities = [], causes = [], outcomes = [], consequences = [], status = 'completed', sources, chronology = {} }) => Object.freeze({
  ...base({ id: `event:${slug}`, entityType: 'event', slug, name, summary, sourceIds: (sources || [start]).map(chapterSourceId) }),
  category,
  importance,
  chapterRange: Object.freeze({ start, end }),
  chronology: Object.freeze({ sequence: chronology.sequence || 0, day: chronology.day || null, timeOfDay: chronology.timeOfDay || null, certainty: chronology.certainty || 'approximate' }),
  participantIds: Object.freeze(participants.map(characterId)),
  organizationIds: Object.freeze(organizations.map(organizationId)),
  locationIds: Object.freeze(locations),
  abilityIds: Object.freeze(abilities.map((slug) => `ability:${slug}`)),
  causes: Object.freeze(causes),
  outcomes: Object.freeze(outcomes),
  consequenceEventIds: Object.freeze(consequences.map((slug) => `event:${slug}`)),
  status,
});

